export function toByteBuffer(value) {
  if (Buffer.isBuffer(value)) {
    return Buffer.from(value);
  }

  if (value instanceof Uint8Array) {
    return Buffer.from(value);
  }

  if (typeof value === "string") {
    return Buffer.from(value, "latin1");
  }

  throw new TypeError("Expected a string, Buffer, or Uint8Array");
}

export function bufferToString(value) {
  return toByteBuffer(value).toString("latin1");
}

export function formatPythonBytes(value) {
  const buffer = toByteBuffer(value);
  let result = "b'";

  for (const byte of buffer.values()) {
    if (byte === 0x5c) {
      result += "\\\\";
      continue;
    }

    if (byte === 0x27) {
      result += "\\'";
      continue;
    }

    if (byte >= 0x20 && byte <= 0x7e) {
      result += String.fromCharCode(byte);
      continue;
    }

    result += `\\x${byte.toString(16).padStart(2, "0")}`;
  }

  return `${result}'`;
}

