const NEGATIVE_NUMBER_RE = /^-\d+(\.\d*)?$|^-\.\d+$/;

function acceptsOptionalValue(token) {
  return token === "-" || !token.startsWith("-") || NEGATIVE_NUMBER_RE.test(token);
}

export function formatUsage(progName) {
  return `usage: ${progName} [-h] --domain DOMAIN\n`;
}

export function formatHelp(progName) {
  return (
    `${formatUsage(progName)}\n` +
    "options:\n" +
    "  -h, --help       show this help message and exit\n" +
    "  --domain DOMAIN\n"
  );
}

export function parseArgs(argv) {
  let domain;
  let awaitingDomainValue = false;
  let stopParsingOptions = false;
  const unknown = [];

  for (const token of argv) {
    if (awaitingDomainValue) {
      if (!acceptsOptionalValue(token)) {
        throw new CLIUsageError("argument --domain: expected one argument");
      }

      domain = token;
      awaitingDomainValue = false;
      continue;
    }

    if (!stopParsingOptions && (token === "-h" || token === "--help")) {
      return { help: true };
    }

    if (!stopParsingOptions && token === "--domain") {
      awaitingDomainValue = true;
      continue;
    }

    if (!stopParsingOptions && token.startsWith("--domain=")) {
      domain = token.slice("--domain=".length);
      continue;
    }

    if (!stopParsingOptions && token === "--") {
      stopParsingOptions = true;
      unknown.push(token);
      continue;
    }

    unknown.push(token);
  }

  if (awaitingDomainValue) {
    throw new CLIUsageError("argument --domain: expected one argument");
  }

  if (domain === undefined) {
    throw new CLIUsageError("the following arguments are required: --domain");
  }

  if (unknown.length > 0) {
    throw new CLIUsageError(`unrecognized arguments: ${unknown.join(" ")}`);
  }

  return { help: false, domain };
}

