const BASE = 36;
const T_MIN = 1;
const T_MAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;
const DELIMITER = "-";

function adapt(delta, numPoints, firstTime) {
  let adjusted = firstTime ? Math.floor(delta / DAMP) : delta >> 1;
  adjusted += Math.floor(adjusted / numPoints);

  let k = 0;
  const threshold = Math.floor(((BASE - T_MIN) * T_MAX) / 2);

  while (adjusted > threshold) {
    adjusted = Math.floor(adjusted / (BASE - T_MIN));
    k += BASE;
  }

  return k + Math.floor((((BASE - T_MIN + 1) * adjusted) / (adjusted + SKEW)));
}

function digitToBasic(digit) {
  return String.fromCharCode(digit + 22 + 75 * Number(digit < 26));
}

function basicToDigit(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) {
    return codePoint - 22;
  }

  if (codePoint >= 0x41 && codePoint <= 0x5a) {
    return codePoint - 0x41;
  }

  if (codePoint >= 0x61 && codePoint <= 0x7a) {
    return codePoint - 0x61;
  }

  return BASE;
}

export function encodePunycode(input) {
  const codePoints = Array.from(input, (char) => char.codePointAt(0));

  let n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;
  let output = "";

  for (const codePoint of codePoints) {
    if (codePoint < 0x80) {
      output += String.fromCodePoint(codePoint);
    }
  }

  let handledCount = output.length;
  const basicLength = handledCount;

  if (basicLength > 0) {
    output += DELIMITER;
  }

  while (handledCount < codePoints.length) {
    let nextCodePoint = Number.MAX_SAFE_INTEGER;

    for (const codePoint of codePoints) {
      if (codePoint >= n && codePoint < nextCodePoint) {
        nextCodePoint = codePoint;
      }
    }

    delta += (nextCodePoint - n) * (handledCount + 1);
    n = nextCodePoint;

    for (const codePoint of codePoints) {
      if (codePoint < n) {
        delta += 1;
      }

      if (codePoint !== n) {
        continue;
      }

      let q = delta;

      for (let k = BASE; ; k += BASE) {
        const t =
          k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;

        if (q < t) {
          break;
        }

        output += digitToBasic(t + ((q - t) % (BASE - t)));
        q = Math.floor((q - t) / (BASE - t));
      }

      output += digitToBasic(q);
      bias = adapt(delta, handledCount + 1, handledCount === basicLength);
      delta = 0;
      handledCount += 1;
    }

    delta += 1;
    n += 1;
  }

  return output;
}

export function decodePunycode(input) {
  let n = INITIAL_N;
  let i = 0;
  let bias = INITIAL_BIAS;
  const output = [];

  const delimiterIndex = input.lastIndexOf(DELIMITER);
  let index = 0;

  if (delimiterIndex >= 0) {
    for (let position = 0; position < delimiterIndex; position += 1) {
      const codePoint = input.charCodeAt(position);

      if (codePoint >= 0x80) {
        throw new Error("Invalid input");
      }

      output.push(codePoint);
    }

    index = delimiterIndex + 1;
  }

  while (index < input.length) {
    const oldI = i;
    let weight = 1;

    for (let k = BASE; ; k += BASE) {
      if (index >= input.length) {
        throw new Error("Invalid input");
      }

      const digit = basicToDigit(input.charCodeAt(index));
      index += 1;

      if (digit >= BASE) {
        throw new Error("Invalid input");
      }

      i += digit * weight;

      const t =
        k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;

      if (digit < t) {
        break;
      }

      weight *= BASE - t;
    }

    const outputLength = output.length + 1;
    bias = adapt(i - oldI, outputLength, oldI === 0);
    n += Math.floor(i / outputLength);
    i %= outputLength;
    output.splice(i, 0, n);
    i += 1;
  }

  return String.fromCodePoint(...output);
