import {
  formatCodePoint,
  formatLabel,
  IDNAError,
  InvalidCodepoint,
} from "./errors.mjs";

const LOWERCASE_LETTER_RE = /^\p{Ll}$/u;
const OTHER_LETTER_RE = /^\p{Lo}$/u;
const MODIFIER_LETTER_RE = /^\p{Lm}$/u;
const NONSPACING_MARK_RE = /^\p{Mn}$/u;
const SPACING_MARK_RE = /^\p{Mc}$/u;
const DECIMAL_NUMBER_RE = /^\p{Nd}$/u;
const MARK_RE = /^\p{M}$/u;

function isAsciiOnly(value) {
  return /^[\x00-\x7f]*$/.test(value);
}

function isValidAsciiLabelCharacter(codePoint) {
  return (
    (codePoint >= 0x41 && codePoint <= 0x5a) ||
    (codePoint >= 0x61 && codePoint <= 0x7a) ||
    (codePoint >= 0x30 && codePoint <= 0x39) ||
    codePoint === 0x2d
  );
}

function isValidUnicodeLabelCharacter(char) {
  return (
    LOWERCASE_LETTER_RE.test(char) ||
    OTHER_LETTER_RE.test(char) ||
    MODIFIER_LETTER_RE.test(char) ||
    NONSPACING_MARK_RE.test(char) ||
    SPACING_MARK_RE.test(char) ||
    DECIMAL_NUMBER_RE.test(char)
  );
}

function checkLabelLength(asciiLabel) {
  if (asciiLabel.length > 63) {
    throw new IDNAError("Label too long");
  }
}

function checkHyphenRestrictions(label) {
  const chars = Array.from(label);

  if (chars[0] === "-" || chars[chars.length - 1] === "-") {
    throw new IDNAError("Label must not start or end with a hyphen");
  }

  if (
    chars.length >= 4 &&
    chars[2] === "-" &&
    chars[3] === "-" &&
    chars.slice(0, 4).join("").toLowerCase() !== "xn--"
  ) {
    throw new IDNAError("Label has disallowed hyphens in 3rd and 4th position");
  }
}

function checkInitialCombiner(chars) {
  if (chars.length > 0 && MARK_RE.test(chars[0])) {
    throw new IDNAError("Label begins with an illegal combining character");
  }
}

function validateUnicodeLabel(label) {
  if (label.length === 0) {
    throw new IDNAError("Empty Label");
  }

  if (label.normalize("NFC") !== label) {
    throw new IDNAError("Label must be in Normalization Form C");
  }

  const chars = Array.from(label);
  checkHyphenRestrictions(label);
  checkInitialCombiner(chars);

  for (let index = 0; index < chars.length; index += 1) {
    const char = chars[index];
    const codePoint = char.codePointAt(0);

    if (codePoint < 0x80) {
      if (
        (codePoint >= 0x61 && codePoint <= 0x7a) ||
        (codePoint >= 0x30 && codePoint <= 0x39) ||
        codePoint === 0x2d
