import {
  CLIUsageError,
  formatHelp,
  formatUsage,
  parseArgs,
} from "./lib/cli/argparse_like.mjs";
import {
  alabel,
  decode,
  encode,
  formatPythonBytes,
  ulabel,
} from "./lib/idna/index.mjs";

function getProgramName() {
  const scriptPath = process.argv[1] ?? "test1.mjs";
  const parts = scriptPath.split(/[\\/]/);
  return parts[parts.length - 1] || "test1.mjs";
}

function writeStdoutLine(value) {
  process.stdout.write(`${value}\n`);
}

function writeUsageError(progName, message) {
  process.stderr.write(formatUsage(progName));
  process.stderr.write(`${progName}: error: ${message}\n`);
}

const progName = getProgramName();

try {
  const args = parseArgs(process.argv.slice(2));

  if (args.help) {
    process.stdout.write(formatHelp(progName));
    process.exit(0);
  }

  const domain = args.domain;

  const encoded = encode(domain);
  writeStdoutLine(formatPythonBytes(encoded));

  const decoded = decode(encoded);
  writeStdoutLine(decoded);

  const firstLabel = domain.split(".")[0];

  if (firstLabel) {
    const ulabelResult = ulabel(encode(firstLabel));
    writeStdoutLine(ulabelResult);

    const alabelResult = alabel(firstLabel);
    writeStdoutLine(formatPythonBytes(alabelResult));
  }
} catch (error) {
  if (error instanceof CLIUsageError) {
    writeUsageError(progName, error.message);
    process.exit(2);
  }

  throw error;
}

