export function formatCodePoint(codePoint) {
  return `U+${codePoint.toString(16).toUpperCase().padStart(4, "0")}`;
}

export function formatLabel(label) {
  let result = "'";

  for (const char of Array.from(label)) {
    const codePoint = char.codePointAt(0);

    if (char === "\\") {
      result += "\\\\";
      continue;
    }

    if (char === "'") {
      result += "\\'";
      continue;
    }

    if (/^\p{C}$/u.test(char)) {
      if (codePoint <= 0xff) {
        result += `\\x${codePoint.toString(16).padStart(2, "0")}`;
      } else if (codePoint <= 0xffff) {
        result += `\\u${codePoint.toString(16).padStart(4, "0")}`;
      } else {
        result += `\\U${codePoint.toString(16).padStart(8, "0")}`;
      }

      continue;
    }

    result += char;
  }

  return `${result}'`;
}

export class IDNAError extends Error {
  constructor(message) {
    super(message);
    this.name = "IDNAError";
  }
}

export class InvalidCodepoint extends IDNAError {
  constructor(codePoint, position, label) {
    super(
      `Codepoint ${formatCodePoint(codePoint)} at position ${position} of ${formatLabel(label)} not allowed`,
    );
    this.name = "InvalidCodepoint";
  }
}

export class InvalidCodepointContext extends IDNAError {
  constructor(message) {
    super(message);
    this.name = "InvalidCodepointContext";
  }
}

