    if (codePoint < 0x80) {
      output += String.fromCodePoint(codePoint);
    }
  }

  const basicLength = output.length;
  let handledCodePoints = basicLength;

  if (basicLength > 0) {
    output += DELIMITER;
  }

  while (handledCodePoints < codePoints.length) {
    let m = Number.MAX_SAFE_INTEGER;

    for (const codePoint of codePoints) {
      if (codePoint >= n && codePoint < m) {
        m = codePoint;
      }
    }

    delta += (m - n) * (handledCodePoints + 1);
    n = m;

    for (const codePoint of codePoints) {
      if (codePoint < n) {
        delta += 1;
      }

      if (codePoint !== n) {
        continue;
      }

      let q = delta;

      for (let k = BASE; ; k += BASE) {
        const threshold = k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;
        if (q < threshold) {
          break;
        }

        output += digitToBasic(threshold + ((q - threshold) % (BASE - threshold)));
        q = Math.floor((q - threshold) / (BASE - threshold));
      }

      output += digitToBasic(q);
      bias = adapt(delta, handledCodePoints + 1, handledCodePoints === basicLength);
      delta = 0;
      handledCodePoints += 1;
    }

    delta += 1;
    n += 1;
  }

  return output;
