export function decodePunycode(input) {
  const output = [];
  const lastDelimiterIndex = input.lastIndexOf(DELIMITER);
  const basicLength = lastDelimiterIndex === -1 ? 0 : lastDelimiterIndex;

  for (let index = 0; index < basicLength; index += 1) {
    const codePoint = input.codePointAt(index);
    if (codePoint >= 0x80) {
      throw new IDNAError('Invalid A-label');
    }
    output.push(codePoint);
  }

  let index = basicLength > 0 ? lastDelimiterIndex + 1 : 0;
  let n = INITIAL_N;
  let i = 0;
  let bias = INITIAL_BIAS;

  while (index < input.length) {
    const previousI = i;
    let weight = 1;

    for (let k = BASE; ; k += BASE) {
      if (index >= input.length) {
        throw new IDNAError('Invalid A-label');
      }

      const digit = basicToDigit(input.codePointAt(index));
      index += 1;

      if (digit >= BASE) {
        throw new IDNAError('Invalid A-label');
      }

      i += digit * weight;

      const threshold = k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;
      if (digit < threshold) {
        break;
      }

      weight *= BASE - threshold;
    }

    const outputLength = output.length + 1;
    bias = adapt(i - previousI, outputLength, previousI === 0);
    n += Math.floor(i / outputLength);
    i %= outputLength;
    output.splice(i, 0, n);
    i += 1;
  }

  try {
    return String.fromCodePoint(...output);
  } catch (error) {
    throw new IDNAError('Invalid A-label');
  }
}

