const RTL_SCRIPT_PATTERN = /^(?:\p{Script=Arabic}|\p{Script=Hebrew}|\p{Script=Syriac}|\p{Script=Thaana}|\p{Script=Nko}|\p{Script=Samaritan}|\p{Script=Mandaic}|\p{Script=Adlam}|\p{Script=Hanifi_Rohingya})$/u;
const GREEK_PATTERN = /^\p{Script=Greek}$/u;
const HEBREW_PATTERN = /^\p{Script=Hebrew}$/u;
const JAPANESE_PATTERN = /^(?:\p{Script=Hiragana}|\p{Script=Katakana}|\p{Script=Han})$/u;
const LOWERCASE_PATTERN = /^\p{Lowercase_Letter}$/u;
const UPPERCASE_OR_TITLECASE_PATTERN = /^(?:\p{Uppercase_Letter}|\p{Titlecase_Letter})$/u;
const OTHER_LETTER_PATTERN = /^\p{Other_Letter}$/u;
const MODIFIER_LETTER_PATTERN = /^\p{Modifier_Letter}$/u;
const DECIMAL_NUMBER_PATTERN = /^\p{Decimal_Number}$/u;
const MARK_PATTERN = /^\p{Mark}$/u;

export function toCodePoints(value) {
  return Array.from(value);
}

export function isDomainSeparator(character) {
  return character === '.' || character === '\u3002' || character === '\uFF0E' || character === '\uFF61';
}

export function splitDomain(domain) {
  const trailingDot = domain.length > 0 && isDomainSeparator(domain[domain.length - 1]);
  const normalized = domain.replace(/[.\u3002\uFF0E\uFF61]/gu, '.');
  return { labels: normalized.split('.'), trailingDot };
}

export function joinDomain(labels, trailingDot) {
  const joined = labels.join('.');
  return trailingDot ? `${joined}.` : joined;
}

export function hasAcePrefix(label) {
  return label.length >= 4 && label.slice(0, 4).toLowerCase() === 'xn--';
}

export function isAscii(character) {
  return character.codePointAt(0) < 0x80;
}

export function isAllAscii(value) {
  for (const character of value) {
    if (!isAscii(character)) {
      return false;
    }
  }
  return true;
}

export function isAsciiLowercaseLetter(character) {
  const codePoint = character.codePointAt(0);
  return codePoint >= 0x61 && codePoint <= 0x7A;
}

export function isAsciiUppercaseLetter(character) {
  const codePoint = character.codePointAt(0);
  return codePoint >= 0x41 && codePoint <= 0x5A;
}

export function isAsciiLetter(character) {
  return isAsciiLowercaseLetter(character) || isAsciiUppercaseLetter(character);
}

export function isAsciiDigit(character) {
  const codePoint = character.codePointAt(0);
  return codePoint >= 0x30 && codePoint <= 0x39;
}

export function isBasicLabelCharacter(character) {
  return isAsciiLetter(character) || isAsciiDigit(character) || character === '-';
}

export function isMark(character) {
  return MARK_PATTERN.test(character);
}

export function isUppercaseOrTitlecaseLetter(character) {
  return UPPERCASE_OR_TITLECASE_PATTERN.test(character);
}

export function isAllowedNonAsciiCodePoint(character) {
  return (
    LOWERCASE_PATTERN.test(character) ||
    OTHER_LETTER_PATTERN.test(character) ||
    MODIFIER_LETTER_PATTERN.test(character) ||
    DECIMAL_NUMBER_PATTERN.test(character) ||
    MARK_PATTERN.test(character)
  );
}

export function isContextualCodePoint(character) {
  return (
    character === '\u00B7' ||
    character === '\u0375' ||
    character === '\u05F3' ||
    character === '\u05F4' ||
    character === '\u30FB' ||
    character === '\u200C' ||
    character === '\u200D'
  );
}

export function isGreek(character) {
  return GREEK_PATTERN.test(character);
}

export function isHebrew(character) {
  return HEBREW_PATTERN.test(character);
}

export function hasJapaneseScript(characters) {
  return characters.some((character) => JAPANESE_PATTERN.test(character));
}

export function isRtlLetter(character) {
  return RTL_SCRIPT_PATTERN.test(character) && !isMark(character) && !isArabicIndicDigit(character) && !isExtendedArabicIndicDigit(character);
}

export function isArabicIndicDigit(character) {
  const codePoint = character.codePointAt(0);
  return codePoint >= 0x0660 && codePoint <= 0x0669;
}

export function isExtendedArabicIndicDigit(character) {
  const codePoint = character.codePointAt(0);
  return codePoint >= 0x06F0 && codePoint <= 0x06F9;
}

export function isLetterLikeForJoiner(character) {
  if (character === undefined) {
    return false;
  }
  return isAsciiLowercaseLetter(character) || isAllowedNonAsciiCodePoint(character) || isRtlLetter(character);
}

export function classifyBidiType(character) {
  if (isMark(character)) {
    return 'NSM';
  }
  if (isAsciiDigit(character)) {
    return 'EN';
  }
  if (isArabicIndicDigit(character) || isExtendedArabicIndicDigit(character)) {
    return 'AN';
  }
  if (character === '\u05F3' || character === '\u05F4') {
    return 'R';
  }
  if (character === '\u00B7' || character === '\u0375' || character === '\u30FB') {
    return 'L';
  }
  if (isRtlLetter(character)) {
    return 'R';
  }
  if (isAsciiLowercaseLetter(character) || isAsciiUppercaseLetter(character) || isAllowedNonAsciiCodePoint(character)) {
    return 'L';
  }
  return 'N';
}

export function hasBidiRelevantCodePoint(characters) {
  return characters.some((character) => {
    const bidiType = classifyBidiType(character);
    return bidiType === 'R' || bidiType === 'AN';
  });
}

