const HELP_TEXT = (programName) =>
  `usage: ${programName} [-h] --domain DOMAIN

options:
  -h, --help       show this help message and exit
  --domain DOMAIN
`;

const usageLine = (programName) => `usage: ${programName} [-h] --domain DOMAIN\n`;

function getProgramName(scriptPath) {
  if (!scriptPath) {
    return 'test1.mjs';
  }

  const slashIndex = Math.max(scriptPath.lastIndexOf('/'), scriptPath.lastIndexOf('\\'));
  return slashIndex === -1 ? scriptPath : scriptPath.slice(slashIndex + 1);
}

function matchLongOption(optionName, candidate) {
  return optionName.startsWith(candidate);
}

function classifyOption(token) {
  if (token === '-h') {
    return { kind: 'help', explicitValue: null };
  }

  if (token.startsWith('-h=')) {
    return { kind: 'help', explicitValue: token.slice(3) };
  }

  if (!token.startsWith('--')) {
    return { kind: 'other', explicitValue: null };
  }

  const body = token.slice(2);
  const equalsIndex = body.indexOf('=');
  const option = equalsIndex === -1 ? body : body.slice(0, equalsIndex);
  const explicitValue = equalsIndex === -1 ? null : body.slice(equalsIndex + 1);

  if (option.length === 0) {
    return { kind: 'other', explicitValue };
  }

  if (matchLongOption('help', option)) {
    return { kind: 'help', explicitValue };
  }

  if (matchLongOption('domain', option)) {
    return { kind: 'domain', explicitValue };
  }

  return { kind: 'other', explicitValue };
}

function looksLikeOption(token) {
  return token.startsWith('-') && token !== '-' && !/^-(?:\d+(?:\.\d+)?|\.\d+)$/.test(token);
}

export function parseCommandLine(argv, scriptPath) {
  const programName = getProgramName(scriptPath);
  const extras = [];
  let domain;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    const option = classifyOption(token);

    if (option.kind === 'help') {
      if (option.explicitValue !== null) {
        return {
          ok: false,
          exitCode: 2,
          stream: 'stderr',
          text:
            usageLine(programName) +
            `${programName}: error: argument -h/--help: ignored explicit argument '${option.explicitValue}'\n`,
        };
      }

      return {
        ok: false,
        exitCode: 0,
        stream: 'stdout',
        text: HELP_TEXT(programName),
      };
    }

    if (option.kind === 'domain') {
      if (option.explicitValue !== null) {
        domain = option.explicitValue;
        continue;
      }

      const next = argv[index + 1];
      if (next === undefined || looksLikeOption(next)) {
        return {
          ok: false,
          exitCode: 2,
          stream: 'stderr',
          text:
            usageLine(programName) +
            `${programName}: error: argument --domain: expected one argument\n`,
        };
      }

      domain = next;
      index += 1;
      continue;
    }

    extras.push(token);
  }

  if (domain === undefined) {
    return {
      ok: false,
      exitCode: 2,
      stream: 'stderr',
      text:
        usageLine(programName) +
        `${programName}: error: the following arguments are required: --domain\n`,
    };
  }

  if (extras.length > 0) {
    return {
      ok: false,
      exitCode: 2,
      stream: 'stderr',
      text:
        usageLine(programName) +
        `${programName}: error: unrecognized arguments: ${extras.join(' ')}\n`,
    };
  }

  return {
    ok: true,
    domain,
    programName,
  };
}

