function basename(pathname) {
  const normalized = String(pathname || '').replace(/\\/g, '/');
  const slashIndex = normalized.lastIndexOf('/');
  return slashIndex === -1 ? normalized : normalized.slice(slashIndex + 1);
}

function isNegativeNumberToken(token) {
  return /^-\d+(?:\.\d+)?$|^-\.\d+$/.test(token);
}

function renderUsage(programName) {
  return `usage: ${programName} [-h] --domain DOMAIN\n`;
}

function renderHelp(programName) {
  return `${renderUsage(programName)}\noptions:\n  -h, --help       show this help message and exit\n  --domain DOMAIN\n`;
}

function renderError(programName, message) {
  return `${renderUsage(programName)}${programName}: error: ${message}\n`;
}

function resolveLongOption(optionToken) {
  const candidates = ['--help', '--domain'].filter((option) => option.startsWith(optionToken));
  if (candidates.length === 1) {
    return candidates[0];
  }
  if (candidates.length > 1 && candidates.includes(optionToken)) {
    return optionToken;
  }
  return null;
}

function parseLongOption(token, nextToken) {
  const equalsIndex = token.indexOf('=');
  const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
  const explicitValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
  const resolved = resolveLongOption(optionToken);

  if (resolved === null) {
    return { kind: 'extra', consumed: 0 };
  }

  if (resolved === '--help') {
    if (explicitValue !== null) {
      return {
        kind: 'exit',
        code: 2,
        stream: 'stderr',
        message: `argument -h/--help: ignored explicit argument '${explicitValue}'`,
      };
    }
    return { kind: 'help', consumed: 0 };
  }

  if (explicitValue !== null) {
    return { kind: 'domain', value: explicitValue, consumed: 0 };
  }

  if (nextToken === undefined || (nextToken.startsWith('-') && nextToken !== '-' && !isNegativeNumberToken(nextToken))) {
    return {
      kind: 'exit',
      code: 2,
      stream: 'stderr',
      message: 'argument --domain: expected one argument',
    };
  }

  return { kind: 'domain', value: nextToken, consumed: 1 };
}

function parseShortOption(token) {
  if (token === '-h' || /^-h[^=]*$/.test(token)) {
    return { kind: 'help' };
  }
  if (token.startsWith('-h=')) {
    return {
      kind: 'exit',
      code: 2,
      stream: 'stderr',
      message: `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
    };
  }
  return { kind: 'extra' };
}

export function parseArguments(argv) {
  const programName = basename(argv[1] || 'test1.mjs') || 'test1.mjs';
  const tokens = argv.slice(2);
  const extras = [];
  let domainValue;

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '--') {
      extras.push(...tokens.slice(index + 1));
      break;
    }

    if (token.startsWith('--')) {
      const parsed = parseLongOption(token, tokens[index + 1]);

      if (parsed.kind === 'help') {
        return { kind: 'exit', code: 0, stream: 'stdout', text: renderHelp(programName) };
      }

      if (parsed.kind === 'exit') {
        return {
          kind: 'exit',
          code: parsed.code,
          stream: parsed.stream,
          text: renderError(programName, parsed.message),
        };
      }

      if (parsed.kind === 'domain') {
        domainValue = parsed.value;
        index += parsed.consumed;
        continue;
      }

      extras.push(token);
      continue;
    }

    if (token.startsWith('-')) {
      const parsed = parseShortOption(token);

      if (parsed.kind === 'help') {
        return { kind: 'exit', code: 0, stream: 'stdout', text: renderHelp(programName) };
      }

      if (parsed.kind === 'exit') {
        return {
          kind: 'exit',
          code: parsed.code,
          stream: parsed.stream,
          text: renderError(programName, parsed.message),
        };
      }

      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  if (domainValue === undefined) {
    return {
      kind: 'exit',
      code: 2,
      stream: 'stderr',
      text: renderError(programName, 'the following arguments are required: --domain'),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'exit',
      code: 2,
      stream: 'stderr',
      text: renderError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return { kind: 'ok', domain: domainValue };
}

export function writeCliResult(result) {
  if (result.stream === 'stderr') {
    process.stderr.write(result.text);
    return;
  }
  process.stdout.write(result.text);
}

