import { decodePunycode, encodePunycode } from './punycode.mjs';
import {
  classifyBidiType,
  hasAcePrefix,
  hasBidiRelevantCodePoint,
  hasJapaneseScript,
  isAllAscii,
  isAllowedNonAsciiCodePoint,
  isArabicIndicDigit,
  isAscii,
  isAsciiDigit,
  isAsciiLowercaseLetter,
  isBasicLabelCharacter,
  isContextualCodePoint,
  isExtendedArabicIndicDigit,
  isGreek,
  isHebrew,
  isLetterLikeForJoiner,
  isMark,
  isUppercaseOrTitlecaseLetter,
  toCodePoints,
} from './unicode.mjs';
import { IDNABidiError, IDNAError, InvalidCodepoint, InvalidCodepointContext } from './errors.mjs';

function checkPlainAsciiLabel(label) {
  if (label.length === 0) {
    throw new IDNAError('Empty Label');
  }

  if (label.length > 63) {
    throw new IDNAError('Label too long');
  }

  if (label.length >= 4 && label[2] === '-' && label[3] === '-' && !hasAcePrefix(label)) {
    throw new IDNAError('Label has disallowed hyphens in 3rd and 4th position');
  }

  if (label.startsWith('-') || label.endsWith('-')) {
    throw new IDNAError('Label must not start or end with a hyphen');
  }

  const characters = toCodePoints(label);
  for (let index = 0; index < characters.length; index += 1) {
    if (!isBasicLabelCharacter(characters[index])) {
      throw new InvalidCodepoint(characters[index].codePointAt(0), index + 1, label);
    }
  }
}

function validateContextualCodePoint(label, characters, index) {
  const character = characters[index];
  const previous = characters[index - 1];
  const next = characters[index + 1];

  if (character === '\u00B7') {
    if (previous === 'l' && next === 'l') {
      return;
    }
  } else if (character === '\u0375') {
    if (next !== undefined && isGreek(next)) {
      return;
    }
  } else if (character === '\u05F3' || character === '\u05F4') {
    if (previous !== undefined && isHebrew(previous)) {
      return;
    }
  } else if (character === '\u30FB') {
    if (hasJapaneseScript(characters)) {
      return;
    }
  } else if (character === '\u200C') {
    let previousIndex = index - 1;
    let nextIndex = index + 1;

    while (previousIndex >= 0 && isMark(characters[previousIndex])) {
      previousIndex -= 1;
    }
    while (nextIndex < characters.length && isMark(characters[nextIndex])) {
      nextIndex += 1;
    }

    if (isLetterLikeForJoiner(characters[previousIndex]) && isLetterLikeForJoiner(characters[nextIndex])) {
      return;
    }
  } else if (character === '\u200D') {
    if (previous !== undefined && isMark(previous)) {
      return;
    }
  }

  throw new InvalidCodepointContext(character.codePointAt(0), index + 1, label);
}

function checkCodePoints(label) {
  const characters = toCodePoints(label);
  let firstArabicIndic;
  let firstExtendedArabicIndic;

  for (let index = 0; index < characters.length; index += 1) {
    const character = characters[index];
    const codePoint = character.codePointAt(0);

    if (isAscii(character)) {
      if (isAsciiLowercaseLetter(character) || isAsciiDigit(character) || character === '-') {
        continue;
      }
      throw new InvalidCodepoint(codePoint, index + 1, label);
    }

    if (isUppercaseOrTitlecaseLetter(character)) {
      throw new InvalidCodepoint(codePoint, index + 1, label);
    }

    if (isContextualCodePoint(character)) {
      validateContextualCodePoint(label, characters, index);
      continue;
    }

    if (!isAllowedNonAsciiCodePoint(character)) {
      throw new InvalidCodepoint(codePoint, index + 1, label);
    }

    if (isArabicIndicDigit(character) && firstArabicIndic === undefined) {
      firstArabicIndic = { codePoint, position: index + 1 };
    }
    if (isExtendedArabicIndicDigit(character) && firstExtendedArabicIndic === undefined) {
      firstExtendedArabicIndic = { codePoint, position: index + 1 };
    }
  }

  if (firstArabicIndic !== undefined && firstExtendedArabicIndic !== undefined) {
    const failingDigit = firstArabicIndic.position <= firstExtendedArabicIndic.position ? firstArabicIndic : firstExtendedArabicIndic;
    throw new InvalidCodepointContext(failingDigit.codePoint, failingDigit.position, label);
  }

  return characters;
}

function checkBidi(label, characters) {
  if (!hasBidiRelevantCodePoint(characters)) {
    return;
  }

  const bidiTypes = characters.map((character) => classifyBidiType(character));
  const firstType = bidiTypes[0];

  if (firstType !== 'L' && firstType !== 'R') {
    throw new IDNABidiError(`First codepoint in label '${label}' must be directionality L, R or AL`);
  }

  if (firstType === 'L') {
    for (let index = 0; index < bidiTypes.length; index += 1) {
      if (bidiTypes[index] === 'R' || bidiTypes[index] === 'AN') {
        throw new IDNABidiError(`Invalid direction for codepoint at position ${index + 1} in a left-to-right label`);
      }
    }
    return;
  }

  let hasEuropeanNumber = false;
  let hasArabicNumber = false;

  for (let index = 0; index < bidiTypes.length; index += 1) {
    if (bidiTypes[index] === 'L') {
      throw new IDNABidiError(`Invalid direction for codepoint at position ${index + 1} in a right-to-left label`);
    }
    if (bidiTypes[index] === 'EN') {
      hasEuropeanNumber = true;
    }
    if (bidiTypes[index] === 'AN') {
      hasArabicNumber = true;
    }
  }

  if (hasEuropeanNumber && hasArabicNumber) {
    throw new IDNABidiError('Can not mix numeral types in a right-to-left label');
  }
}

export function validateUnicodeLabel(label) {
  if (label.length === 0) {
    throw new IDNAError('Empty Label');
  }

  if (label.length >= 4 && label[2] === '-' && label[3] === '-') {
    throw new IDNAError('Label has disallowed hyphens in 3rd and 4th position');
  }

  if (label.startsWith('-') || label.endsWith('-')) {
    throw new IDNAError('Label must not start or end with a hyphen');
  }

  const characters = toCodePoints(label);
  if (characters.length > 0 && isMark(characters[0])) {
    throw new IDNAError('Label begins with an illegal combining character');
  }

  if (label.normalize('NFC') !== label) {
    throw new IDNAError('Label must be in Normalization Form C');
  }

  const checkedCharacters = checkCodePoints(label);
  checkBidi(label, checkedCharacters);
}

export function decodeAceLabel(label) {
  if (label.length === 0) {
    throw new IDNAError('Empty Label');
  }

  if (label.length > 63) {
    throw new IDNAError('Label too long');
  }

  if (!hasAcePrefix(label)) {
    checkPlainAsciiLabel(label);
    return label.toLowerCase();
  }

  if (label.length === 4) {
    throw new IDNAError('Malformed A-label, no Punycode eligible content found');
  }

  if (label.endsWith('-')) {
    throw new IDNAError('A-label must not end with a hyphen');
  }

  const punycodePayload = label.slice(4).toLowerCase();
  const decoded = decodePunycode(punycodePayload);
  validateUnicodeLabel(decoded);

  if (encodePunycode(decoded).toLowerCase() !== punycodePayload) {
    throw new IDNAError('Invalid A-label');
  }

  return decoded;
}

export function encodeLabel(label) {
  if (label.length === 0) {
    throw new IDNAError('Empty Label');
  }

  if (isAllAscii(label)) {
    if (hasAcePrefix(label)) {
      decodeAceLabel(label);
      return label;
    }

    checkPlainAsciiLabel(label);
    return label;
  }

  validateUnicodeLabel(label);
  const encoded = `xn--${encodePunycode(label)}`;

  if (encoded.length > 63) {
    throw new IDNAError('Label too long');
  }

  return encoded;
}

