const ASCII_RE = /^[\x00-\x7F]*$/;
const COMBINING_MARK_RE = /^\p{M}$/u;
const LETTER_RE = /^(?:\p{Ll}|\p{Lo}|\p{Lm})$/u;
const RTL_SCRIPT_RE = /[\p{Script=Arabic}\p{Script=Hebrew}]/u;
const RTL_NUMERAL_RE = /[\u0660-\u0669\u06F0-\u06F9]/u;
const UPPERCASE_RE = /^(?:\p{Lu}|\p{Lt})$/u;
const VALID_UNICODE_RE = /^(?:\p{Ll}|\p{Lo}|\p{Lm}|\p{Mn}|\p{Mc}|\p{Nd}|-)$/u;

export function toCodePoints(text) {
  return Array.from(text);
}

export function isAscii(text) {
  return ASCII_RE.test(text);
}

export function hasAcePrefix(label) {
  return label.length >= 4 && label.slice(0, 4).toLowerCase() === 'xn--';
}

export function normalizeDomainSeparators(text) {
  return text.replace(/[\u3002\uFF0E\uFF61]/gu, '.');
}

export function splitDomain(text) {
  const normalized = normalizeDomainSeparators(text);
  const trailingDot = normalized.endsWith('.');
  const labels = normalized.split('.');

  if (trailingDot) {
    labels.pop();
  }

  return { normalized, labels, trailingDot };
}

export function formatCodePoint(character) {
  return `U+${character.codePointAt(0).toString(16).toUpperCase().padStart(4, '0')}`;
}

export function findCodePointIndex(text, predicate) {
  const codePoints = toCodePoints(text);

  for (let index = 0; index < codePoints.length; index += 1) {
    if (predicate(codePoints[index])) {
      return index + 1;
    }
  }

  return -1;
}

export function isCombiningMark(character) {
  return COMBINING_MARK_RE.test(character);
}

export function isUppercaseLetter(character) {
  return UPPERCASE_RE.test(character);
}

export function isLetter(character) {
  return LETTER_RE.test(character);
}

export function isRtlLabel(text) {
  return RTL_SCRIPT_RE.test(text);
}

export function startsWithRtlNumeral(text) {
  const [first = ''] = toCodePoints(text);
  return RTL_NUMERAL_RE.test(first);
}

export function isValidUnicodeCodePoint(character) {
  return VALID_UNICODE_RE.test(character);
}

