import { IDNAError } from './errors.mjs';

const BASE = 36;
const T_MIN = 1;
const T_MAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;
const DELIMITER = '-';

function adapt(delta, numPoints, firstTime) {
  let adjustedDelta = firstTime ? Math.floor(delta / DAMP) : Math.floor(delta / 2);
  adjustedDelta += Math.floor(adjustedDelta / numPoints);

  let k = 0;
  while (adjustedDelta > Math.floor(((BASE - T_MIN) * T_MAX) / 2)) {
    adjustedDelta = Math.floor(adjustedDelta / (BASE - T_MIN));
    k += BASE;
  }

  return k + Math.floor(((BASE - T_MIN + 1) * adjustedDelta) / (adjustedDelta + SKEW));
}

function basicToDigit(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) {
    return codePoint - 22;
  }
  if (codePoint >= 0x41 && codePoint <= 0x5A) {
    return codePoint - 0x41;
  }
  if (codePoint >= 0x61 && codePoint <= 0x7A) {
    return codePoint - 0x61;
  }
  return BASE;
}

function digitToBasic(digit) {
  if (digit < 26) {
    return String.fromCharCode(0x61 + digit);
  }
  return String.fromCharCode(0x30 + digit - 26);
}

export function encodePunycode(input) {
  const codePoints = Array.from(input, (character) => character.codePointAt(0));
  let n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;
  let output = '';

  for (const codePoint of codePoints) {
    if (codePoint < 0x80) {
      output += String.fromCodePoint(codePoint);
    }
  }

  const basicLength = output.length;
  let handledCodePoints = basicLength;

  if (basicLength > 0) {
    output += DELIMITER;
  }

  while (handledCodePoints < codePoints.length) {
    let m = Number.MAX_SAFE_INTEGER;

    for (const codePoint of codePoints) {
      if (codePoint >= n && codePoint < m) {
        m = codePoint;
      }
    }

    delta += (m - n) * (handledCodePoints + 1);
    n = m;

    for (const codePoint of codePoints) {
      if (codePoint < n) {
        delta += 1;
      }

      if (codePoint !== n) {
        continue;
      }

      let q = delta;

      for (let k = BASE; ; k += BASE) {
        const threshold = k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;
        if (q < threshold) {
          break;
        }

        output += digitToBasic(threshold + ((q - threshold) % (BASE - threshold)));
        q = Math.floor((q - threshold) / (BASE - threshold));
      }

      output += digitToBasic(q);
      bias = adapt(delta, handledCodePoints + 1, handledCodePoints === basicLength);
      delta = 0;
      handledCodePoints += 1;
    }

    delta += 1;
    n += 1;
  }

  return output;
}

export function decodePunycode(input) {
  const output = [];
  const lastDelimiterIndex = input.lastIndexOf(DELIMITER);
  const basicLength = lastDelimiterIndex === -1 ? 0 : lastDelimiterIndex;

  for (let index = 0; index < basicLength; index += 1) {
    const codePoint = input.codePointAt(index);
    if (codePoint >= 0x80) {
      throw new IDNAError('Invalid A-label');
    }
    output.push(codePoint);
  }

  let index = basicLength > 0 ? lastDelimiterIndex + 1 : 0;
  let n = INITIAL_N;
  let i = 0;
  let bias = INITIAL_BIAS;

  while (index < input.length) {
    const previousI = i;
    let weight = 1;

    for (let k = BASE; ; k += BASE) {
      if (index >= input.length) {
        throw new IDNAError('Invalid A-label');
      }

      const digit = basicToDigit(input.codePointAt(index));
      index += 1;

      if (digit >= BASE) {
        throw new IDNAError('Invalid A-label');
      }

      i += digit * weight;

      const threshold = k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;
      if (digit < threshold) {
        break;
      }

      weight *= BASE - threshold;
    }

    const outputLength = output.length + 1;
    bias = adapt(i - previousI, outputLength, previousI === 0);
    n += Math.floor(i / outputLength);
    i %= outputLength;
    output.splice(i, 0, n);
    i += 1;
  }

  try {
    return String.fromCodePoint(...output);
  } catch (error) {
    throw new IDNAError('Invalid A-label');
  }
}
